mapper.select:
select customer_tel as customerTel, max(case when ifnull(is_connected, 0) = 1 then 2 else 1 end) as callStatus from mmba_call_record_audit where customer_tel is not null and customer_tel != '' and customer_tel in
#{customerTel}
group by customer_tel

select latest.friend_phone as friendSearch, cast(max(case when current_audit.is_friend = '1' then 1 else 0 end) as unsigned) as wxFriendAdded from ( select friend_phone, staff_id_in_app, max(`timestamp`) as latest_timestamp from mmba_wx_friend_change_audit where behavior_type = 60 and um = #{um} and friend_phone in
#{friendSearch}
and staff_id_in_app in
#{staffIdInApp}
group by friend_phone, staff_id_in_app ) latest join mmba_wx_friend_change_audit current_audit on current_audit.friend_phone = latest.friend_phone and current_audit.staff_id_in_app = latest.staff_id_in_app and current_audit.`timestamp` = latest.latest_timestamp where current_audit.behavior_type = 60 and current_audit.um = #{um} group by latest.friend_phone

select latest.friend_phone from ( select friend_phone, staff_id_in_app, max(`timestamp`) as latest_timestamp from mmba_wx_friend_change_audit where behavior_type = 60 and um = #{um} and friend_phone in
#{friendPhone}
and staff_id_in_app in
#{staffIdInApp}
group by friend_phone, staff_id_in_app ) latest join mmba_wx_friend_change_audit current_audit on current_audit.friend_phone = latest.friend_phone and current_audit.staff_id_in_app = latest.staff_id_in_app and current_audit.`timestamp` = latest.latest_timestamp where current_audit.behavior_type = 60 and current_audit.um = #{um} and current_audit.is_friend = '1' group by latest.friend_phone

select exists(
    select 1
    from (
        select result.friend_phone,
               result.um_wxid,
               max(ifnull(result.timestamp_value, ifnull(result.insert_time_value, result.update_time))) as latest_sort_time
        from mmba_command_result result
        where result.behavior_type = 50
          and result.um = #{um}
          and result.friend_phone = #{friendPhone}
          and result.um_wxid in

            #{umWxid}

        group by result.friend_phone, result.um_wxid
    ) latest
    join mmba_command_result current_result
      on current_result.behavior_type = 50
     and current_result.um = #{um}
     and current_result.friend_phone = latest.friend_phone
     and current_result.um_wxid = latest.um_wxid
     and ifnull(current_result.timestamp_value, ifnull(current_result.insert_time_value, current_result.update_time)) = latest.latest_sort_time
    where current_result.process_status = 4
)

select latest.friend_phone from ( select result.friend_phone, result.um_wxid, max(ifnull(result.timestamp_value, ifnull(result.insert_time_value, result.update_time))) as latest_sort_time from mmba_command_result result where result.behavior_type = 50 and result.um = #{um} and result.friend_phone in
#{friendPhone}
and result.um_wxid in
#{umWxid}
group by result.friend_phone, result.um_wxid ) latest join mmba_command_result current_result on current_result.behavior_type = 50 and current_result.um = #{um} and current_result.friend_phone = latest.friend_phone and current_result.um_wxid = latest.um_wxid and ifnull(current_result.timestamp_value, ifnull(current_result.insert_time_value, current_result.update_time)) = latest.latest_sort_time where current_result.process_status = 4 group by latest.friend_phone

select * from mmba_call_record_audit where 1 = 1
and req_id = #{request.reqId}
and um = #{request.um}
and device_id = #{request.deviceId}
and (imei = #{request.imei} or imei2 = #{request.imei})
and customer_tel like concat('%', #{request.customerTel}, '%')
and staff_name like concat('%', #{request.staffName}, '%')
and ( req_id like concat('%', #{request.keyword}, '%') or customer like concat('%', #{request.keyword}, '%') or customer_tel like concat('%', #{request.keyword}, '%') or staff_name like concat('%', #{request.keyword}, '%') or device_id like concat('%', #{request.keyword}, '%') )
order by begin_timestamp desc, timestamp desc, es_id desc

select * from mmba_sms_record_audit where 1 = 1
and req_id = #{request.reqId}
and um = #{request.um}
and device_id = #{request.deviceId}
and (imei = #{request.imei} or imei2 = #{request.imei})
and customer_tel like concat('%', #{request.customerTel}, '%')
and type = #{request.type}
and staff_name like concat('%', #{request.staffName}, '%')
and ( req_id like concat('%', #{request.keyword}, '%') or customer like concat('%', #{request.keyword}, '%') or customer_tel like concat('%', #{request.keyword}, '%') or content like concat('%', #{request.keyword}, '%') or staff_name like concat('%', #{request.keyword}, '%') )
order by timestamp desc, create_time desc, es_id desc

select * from mmba_wx_chat_audit where 1 = 1
and req_id = #{request.reqId}
and um = #{request.um}
and device_id = #{request.deviceId}
and (imei = #{request.imei} or imei2 = #{request.imei})
and staff_name like concat('%', #{request.staffName}, '%')
and friend_phone like concat('%', #{request.friendPhone}, '%')
and customer_account like concat('%', #{request.customerAccount}, '%')
and customer_account_id like concat('%', #{request.customerAccountId}, '%')
and chat_type = #{request.chatType}
and ( req_id like concat('%', #{request.keyword}, '%') or content like concat('%', #{request.keyword}, '%') or customer like concat('%', #{request.keyword}, '%') or customer_account like concat('%', #{request.keyword}, '%') or friend_phone like concat('%', #{request.keyword}, '%') or staff_name like concat('%', #{request.keyword}, '%') )
order by timestamp desc, time desc, es_id desc

select * from mmba_wx_friend_change_audit where 1 = 1
and um = #{request.um}
and device_id = #{request.deviceId}
and (imei = #{request.imei} or imei2 = #{request.imei})
and staff_name like concat('%', #{request.staffName}, '%')
and staff_id_in_app like concat('%', #{request.staffIdInApp}, '%')
and friend_phone like concat('%', #{request.friendPhone}, '%')
and oper_flag = #{request.operFlag}
and ( contact_im_app_nick_name like concat('%', #{request.keyword}, '%') or contact_im_app_account like concat('%', #{request.keyword}, '%') or friend_phone like concat('%', #{request.keyword}, '%') or contact_mobile like concat('%', #{request.keyword}, '%') or staff_name like concat('%', #{request.keyword}, '%') )
order by timestamp desc, create_time desc, es_id desc

select * from mmba_wx_login_audit where 1 = 1
and um = #{request.um}
and device_id = #{request.deviceId}
and staff_name like concat('%', #{request.staffName}, '%')
and staff_id_in_app like concat('%', #{request.staffIdInApp}, '%')
and staff_im_app_account like concat('%', #{request.staffImAppAccount}, '%')
and device_name like concat('%', #{request.deviceName}, '%')
and login_status = #{request.loginStatus}
and ( staff_name like concat('%', #{request.keyword}, '%') or device_name like concat('%', #{request.keyword}, '%') or staff_id_in_app like concat('%', #{request.keyword}, '%') or staff_im_app_account like concat('%', #{request.keyword}, '%') )
order by create_time desc, id desc

select * from mmba_device_info_audit where 1 = 1
and um = #{request.um}
and device_id = #{request.deviceId}
and (imei = #{request.imei} or imei2 = #{request.imei})
and staff_name like concat('%', #{request.staffName}, '%')
and (phone like concat('%', #{request.phone}, '%') or phone2 like concat('%', #{request.phone}, '%'))
and (iccid like concat('%', #{request.iccid}, '%') or iccid2 like concat('%', #{request.iccid}, '%'))
and device_type = #{request.deviceType}
and ( device_id like concat('%', #{request.keyword}, '%') or imei like concat('%', #{request.keyword}, '%') or imei2 like concat('%', #{request.keyword}, '%') or phone like concat('%', #{request.keyword}, '%') or phone2 like concat('%', #{request.keyword}, '%') or staff_name like concat('%', #{request.keyword}, '%') )
order by timestamp desc, change_time desc, id desc
